pragma solidity 0.8.24;

import 'forge-std/Test.sol';
import {CLOBHelper} from 'src/handlers/clob/libraries/CLOBHelper.sol';

contract EndingOrderNonceSlot0Test is Test {
    using CLOBHelper for OrderBook;

    function testEndingOrderNonceWhenBookExhausted() public {
        // Setup order book with exactly 1 order of amount X
        // Fill entire order book (inputAmount == order.inputAmount)
        // Capture the emitted OrderBookFill event
        // Assert: endingOrderNonce == value at storage slot 0 (reentrancy guard state)
        // vs expected: some sentinel like 0 or type(uint256).max
        vm.recordLogs();
        // ... fillOrder with exact input to exhaust book ...
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Find OrderBookFill, decode endingOrderNonce, assert it's wrong
        uint256 emittedNonce = abi.decode(logs[0].data, (uint256, uint256, uint256))[1];
        // Should be slot-0 content, not a valid order nonce
        assertEq(emittedNonce, 1, 'reads reentrancy guard NOT_ENTERED = 1');
    }
}

