pragma solidity 0.8.24;

import 'forge-std/Test.sol';

contract GasGriefHandler {
    function ammHandleTransfer(bytes calldata) external returns (bytes memory) {
        // Return 1MB of data on revert
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0) // signal: returning huge error
            revert(ptr, 1048576) // 1MB revert data
        }
    }
}

contract TransferHandlerMemoryExpansionTest is Test {
    function testMemoryExpansionBeforeSuccessCheck() public {
        GasGriefHandler handler = new GasGriefHandler();
        uint256 gasBefore = gasleft();
        // Call AMMModule._executeTransferHandler via the swap path
        // Measure gas consumption difference
        // Assert: gas consumed >> expected for a simple revert
        uint256 gasAfter = gasleft();
        uint256 gasUsed = gasBefore - gasAfter;
        // With 1MB expansion, expect ~3M gas overhead
        assertGt(gasUsed, 1_000_000, 'memory expansion increases gas cost');
    }
}

