contract CP006ExtractionTest is Test {
    uint256 constant Q96 = 2**96;

    function test_calculateFixedInput_doubleRounding_exceeds_single() public pure {
        uint256 amountIn = 1e18;
        uint160 sqrtPriceX96 = 4_295_128_739 + 1_000_000; // valid price near MIN

        // Single-round reference (correct price):
        uint256 intermediate = FullMath.mulDiv(amountIn, sqrtPriceX96, Q96);
        uint256 singleRound = FullMath.mulDiv(intermediate, sqrtPriceX96, Q96);

        // Double-round (actual):
        uint256 r1 = FullMath.mulDivRoundingUp(amountIn, sqrtPriceX96, Q96);
        uint256 r2 = FullMath.mulDivRoundingUp(r1, sqrtPriceX96, Q96);

        assertGe(r2, singleRound, 'double-round >= single-round (over-credits maker)');
        uint256 excess = r2 - singleRound;
        assertLe(excess, 2, 'excess <= 2 wei per call');
    }

    function test_fillOrder_accumulated_rounding_across_N_steps(uint8 N) public {
        vm.assume(N >= 2 && N <= 50);
        // Setup CLOBTransferHandler with N orders of 1e15 each at price P
        // Execute fill of N * 1e15 tokenIn
        // Measure: executorRefund vs expected (N * 1e15 * price - exact_math)
        // Assert: executorRefund < exact_math_refund by up to 2*N wei
    }
}

