pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract FeeOnTopExtractionTest is Test {
    // Setup: AMM + PermitTransferHandler + WETH/USDC mocks
    // User signs partial fill permit: limitAmount=1000e6, amountSpecified=1e18 (1 ETH)
    // Pool: 1050e6 USDC = 1e18 ETH (5% positive slippage available)

    function test_executor_extracts_positive_slippage_via_feeOnTop() public {
        uint256 executorUSDCBefore = usdc.balanceOf(executor);
        uint256 userETHBefore = weth.balanceOf(user);

        // Executor tunes feeOnTop to capture ~47 USDC of the 50 USDC slippage
        // 953 USDC -> pool -> ~1.001 ETH (just above user's 1 ETH minimum)
        _executePartialFillWithFeeOnTop({
            permitLimitAmount: 1000e6,
            permitAmountSpecified: 1e18,
            feeOnTopFlatAmount: 47e6  // 47 USDC extracted as unsigned fee
        });

        uint256 executorUSDCAfter = usdc.balanceOf(executor);
        uint256 userETHAfter = weth.balanceOf(user);

        // User got minimum ETH (not the market 1.05 ETH)
        assertApproxEqRel(userETHAfter - userETHBefore, 1e18, 0.005e18);
        // Executor extracted feeOnTop
        assertEq(executorUSDCAfter - executorUSDCBefore, 47e6);
    }
}

