pragma solidity 0.8.24;
import 'forge-std/Test.sol';
import {CLOBHelper} from 'src/handlers/clob/libraries/CLOBHelper.sol';
import {SqrtPriceCalculator} from 'some/path/SqrtPriceCalculator.sol';

contract PriceBoundBypassTest is Test {
    uint256 constant Q96 = 2**96;

    function test_price_bound_bypass_via_double_rounding() public pure {
        uint160 minBound = 4_295_128_739 + 100_000; // example minSqrtPriceX96
        uint256 orderAmount = 1e18;

        // Find sqrtPriceX96 < minBound where calculateFixedInput produces
        // an amountOut that makes computeRatioX96 return >= minBound
        for (uint160 p = minBound - 1; p >= minBound - 10; p--) {
            uint256 amountOut = CLOBHelper.calculateFixedInput(orderAmount, p);
            uint256 effectivePrice = SqrtPriceCalculator.computeRatioX96(amountOut, orderAmount);
            if (effectivePrice >= uint256(minBound)) {
                // Found bypass: order at price p < minBound passes hook validation
                emit log_named_uint('bypass price', p);
                emit log_named_uint('effective price after rounding', effectivePrice);
                assertTrue(true, 'price bound bypass found via double-rounding');
                return;
            }
        }
        // If no bypass found: test documents the bound is tight enough
        emit log('no bypass in test range - rounding margin too small');
    }
}
